B06=list(Q.keys())
assert len(B06)==20, len(B06)
for cid in B06:
    assert cid not in P
    with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(Q[cid],f,ensure_ascii=False,indent=1)
print("B06 written",len(B06))

# verify all 40 by exact id list
ids=["DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007","LR-001","LR2-013","LR2-014","LR2-015","LR2-016","LR2-017","LR2-018","LR2-019","LR2-020","LR2-021","LR2-022","LR2-023","LR2-024","LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
cm=ru=di=0; ly=set(["DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"])
for cid in ids:
    d=json.load(open(os.path.join(BASE,cid+".json"),encoding="utf-8"))
    assert d["case_id"]==cid and d["prediction_text"] and d["basis"] and 0<=d["confidence"]<=1 and set(d["trigger"])== {"changed_main","reserve_used","disputed","reason"}
    if cid in ly:
        t=d["trigger"]; cm+=t["changed_main"]; ru+=t["reserve_used"]; di+=t["disputed"]
    else:
        assert d["trigger"]=={"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}, cid
print("verified 40; liuyao trigger counts changed_main/reserve_used/disputed =",cm,ru,di)
